(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["kk"] = {"ui":{"skip":"Мазмұнға өту","back":"← AI-gile-ге оралу","lang.button":"Тіл: {name}","lang.dialog":"Тілді таңдаңыз","lang.search":"Тілдерді іздеу","lang.none":"Сәйкес тіл жоқ","lang.notYet":"{name} әлі аударылмаған","theme.aria":"Жарық және қараңғы тақырып арасында ауысу","theme.toLight":"Жарық тақырыпқа ауысу","theme.toDark":"Қараңғы тақырыпқа ауысу","index.title":"AI-gile: AI әзірлеу командаңыз бір тақтада","index.description":"AI-gile: бағдарламалайтын AI командаларына арналған канбан тақтасы. Олар сіз ұйықтап жатқанда жұмыс істейді; сізге шешуге, сынауға және қабылдауға арналған бір қысқа үйінді қалады.","hero.logoAlt":"AI-gile тақтасының белгішесі","hero.h1.html":"AI әзірлеу командаңыз бір&nbsp;тақтада.","hero.alpha":"🐣 Жабық пре-альфа","hero.alphaTitle":"Әлі ерте әрі аяқталмаған: сынағаныңызға рахмет!","hero.lede":"Олар сіз ұйықтап жатқанда жасайды. Сіз бір қысқа үйіндіге оянасыз: бірнеше сұрақ, сынайтын бірнеше нәрсе, бір-екі күлгін ромб. Басыңыз, қабылдаңыз да, кофеңізге оралыңыз.","dl.windows":"Windows қолданбасы","dl.browser":"Браузерде іске қосу","dl.soon":"Жақында","dl.notify":"🔔 Ашылғанда хабарлаңыз","dl.notifySmall":"Альфа немесе бета","hero.secondary":"Agile, бірақ команда ешқашан тұрып ішетін кофесіз-ақ жүре алады. (Стендаптарды бәрібір өткізеді.)","pitch.h2":"AI-gile қалағаныңызша көп сөзбен","pitch.lede":"Ұзындықты таңдаңыз: бір сөзден 144-ке дейін. Әр ұзындық сол көлемге арнап жазылған жеке сипаттама. Жүгірткіні сүйреңіз немесе көрсеткі пернелерін пайдаланыңыз.","pitch.rangeLabel":"Сөзбен берілген ұзындық","pitch.dice":"🎲 басқа нұсқа","pitch.words.one":"{n} сөз","pitch.words.other":"{n} сөз","pitch.letters.one":"{n} әріп","pitch.letters.other":"{n} әріп","pitch.chars.one":"{n} таңба","pitch.chars.other":"{n} таңба","count.line.html.one":"Қазір тақтада {n} карта бар","count.line.html.other":"Қазір тақтада {n} карта бар","features.aria":"Не істейді","f.pile.h":"Сізге арналған бір үйінді","f.pile.html":"<b>Сізге</b> барлық жобалардан сізді күтіп тұрған нәрсенің бәрін жинайды: сұрақтар, сынайтын нәрселер, тек адам орындай алатын тапсырмалар. Кезегіңіз келесі не екенін және қанша уақыт алатынын айтады.","f.sleep.h":"Сіз ұйықтағанда жұмыс істейтін командалар","f.sleep.p":"Әр жобада лид және AI агенттер командасы бар. Картаға пікір қалдырсаңыз, команда оянып, жұмысты істейді де, шаршаған адам да орындай алатын қадамдармен қайтарады.","f.tester.h":"Алдымен AI тестілеуші тексереді","f.tester.p":"Сізге бірдеңе жетпес бұрын, тестілеуші қолданбаның көшірмесінде қадамдарды орындап, не көргенін скриншотпен көрсетеді. Өткендерін парақтап шығып, бір басумен қабылдаңыз.","f.proof.h":"Уәде емес, дәлел","f.proof.p":"Әр тапсыру не өзгергенін көрсетеді: файлдарды, айырмашылықты, скриншоттарды. Біткенін білу үшін әр қолданбаны ашудың қажеті жоқ.","f.chat.h":"Лидтеріңізбен сөйлесіңіз","f.chat.p":"Discord стиліндегі бүйір панель: әр жобаға бір белгіше, сізге керек нәрсеге күлгін ромбтар. Лидке идея жазыңыз; ол оны карталарға және жоспарға айналдырады, ✅ Бастау түймесімен.","f.tidy.h":"Өзін-өзі жинап отырады","f.tidy.p":"Ұқсас карталар біреуге біріктіріледі, түсініксіз атаулар түзетіледі, ал токендерді тексеру кодты жеңіл ұстайды. Ауысатын нәрсе аз, ойлайтын нәрсе аз.","f.private.h":"Сіздікі, өз компьютеріңізде","f.private.li1":"Тақта өз құрылғыңызда жұмыс істейді және тек сізге жауап береді.","f.private.li2":"Адамдар арасындағы жеке хабарлар басынан аяғына дейін шифрланған.","f.private.li3":"Аккаунттар жоқ, трекерлер жоқ, cookie жоқ.","f.lang.h":"Сіздің тіліңізде","f.lang.p":"120-дан астам тіл: голланд, валлий және жапон тілдерінен бастап қарақшы, Йода және клингон тіліне дейін, әзірлеушілердің сөздері үшін ағылшынға жылдам оралу мүмкіндігімен.","tl.aria":"Алғашқы әңгімеден жол картасына дейінгі уақыт сызығы","tl.h2":"Алғашқы чаттан кейінгі жоспарға дейін","tl.lede":"Нақты күндер мен уақыттар, өз уақыт белдеуіңізде. Бүгіннен кейін бұл жоспар, күндер уәде етілмейді.","tl.today":"Бүгін","tl.planned":"жоспарда","tl.cards.one":"{n} карта","tl.cards.other":"{n} карта","join.h2":"Қосылыңыз","join.lede":"AI-gile-ді бір кішкентай адам және көптеген шыдамды агент жасап жатыр. Әзірге ол жабық, достармен жабық альфада. Ашылғанда байқап көргіңіз келе ме?","join.btn":"Қызығушылықты тіркеу","join.small":"Хат жазамыз, басқа ештеңе жоқ","footer.tag":"AI-gile. Трекерсіз, cookie-сіз, тұрып ішетін кофесіз.","footer.licence":"Бизнес лицензиясы","footer.status":"Күйі","form.sending":"Жіберілуде…","form.failed":"Болмады: кейінірек қайталап көріңіз.","form.offline":"AI-gile-ге қосыла алмадық: кейінірек қайталап көріңіз.","interest.title":"AI-gile: альфа ашылғанда хабарлаңыз","interest.description":"AI-gile-дің жабық альфасы немесе бетасы ашылғанда білу үшін электрондық поштаңызды қалдырыңыз.","interest.h1":"🔔 Ашылғанда хабарлаңыз","interest.lede":"AI-gile жабық пре-альфада. Поштаңызды қалдырыңыз, сізге орын болғанда бір рет жазамыз.","interest.email":"Электрондық поштаңыз","interest.which":"Қай сынақ?","interest.alpha":"Жабық альфа: ерте, өрескел, өзгеріс көп","interest.beta":"Бета: тұрақтырақ, кейінірек","interest.both":"Қайсысы, қайсысы болса да, бірінші келгені","interest.submit":"Тізімге қосыңыздар","interest.thanks":"Рахмет! Сіз тізімдесіз.","interest.kept":"Тек поштаңыз бен таңдаған сынағыңыз сақталады, тек осы тізім үшін. Ақпараттық бюллетень жоқ, трекерлер жоқ.","licence.title":"AI-gile: бизнес лицензиясы","licence.description":"AI-gile-ді бизнесіңізде пайдаланасыз ба? Тегін бизнес лицензиясына өтінім беріңіз.","licence.h1":"📜 Бизнес лицензиясы","licence.lede":"AI-gile-ді жұмыста пайдаланасыз ба? Кім екеніңізді және немен айналысатыныңызды айтыңыз. Пайдасы болса, лицензия тегін.","licence.company":"Компания","licence.website":"Веб-сайт","licence.what":"Немен айналысасыз","licence.how":"Әлемге қалай көмектеседі","licence.email":"Электрондық пошта","licence.submit":"Өтінім беру","licence.thanks":"Рахмет! Поштамен жауап береміз.","status.title":"AI-gile күйі","status.h1":"AI-gile күйі","status.quiet":"Бәрі тыныш","status.checking":"Тексерілуде…","status.offline":"Қазір күй қызметіне қосыла алмай тұрмыз (қайталап жатырмыз)","status.updated":"жаңартылды: {ago}","status.justNow":"жаңа ғана","status.min":"{n} мин бұрын","status.hours":"{n} сағ бұрын","status.days":"{n} күн бұрын","live.h2":"Оның қалай салынып жатқанын тікелей көріңіз","live.caption":"Әр карточка жасырылған: сіз жұмыстың пішінін көресіз, сөздерін емес.","live.watching.one":"тікелей: {n} қарап отыр","live.watching.other":"тікелей: {n} қарап отыр","live.offline":"Тікелей тақта аздап тынығып жатыр. Жақында қайта кіріңіз.","live.cols":"Backlog|Орындау керек|Орындалуда|Команда тексеруде|Сізге тесттеу үшін|Командаға|Дайын","live.last.now":"Соңғы карточка дәл қазір жылжытылды","live.last.min.one":"Соңғы карточка {n} минут бұрын жылжытылды","live.last.min.other":"Соңғы карточка {n} минут бұрын жылжытылды","live.last.hour.one":"Соңғы карточка {n} сағат бұрын жылжытылды","live.last.hour.other":"Соңғы карточка {n} сағат бұрын жылжытылды","live.last.day.one":"Соңғы карточка {n} күн бұрын жылжытылды","live.last.day.other":"Соңғы карточка {n} күн бұрын жылжытылды"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботтар.","Тапсырылды."]},{"n":2,"texts":["Робот канбаны.","Агенттер, реттелген.","Идеялар, жасалған."]},{"n":3,"texts":["Роботтарға арналған канбан.","Идея мүмкіндікке айналады.","Тегін агент канбаны."]},{"n":5,"texts":["Агенттер жүргізетін канбан тақтасы.","Сіз карта жазасыз. Агенттер жасайды.","Тегін, жергілікті, тексерілген, сәл ақымақ."]},{"n":8,"texts":["Мұнда AI агенттер жұмыс істейтін тегін канбан тақтасы.","Идеяны жазыңыз. Агенттер жасайды. Сіз қабылдайсыз.","Бір адам мен көптеген шыдамды робот үшін Agile."]},{"n":13,"texts":["Компьютеріңіздегі канбан тақтасы, мұнда карталарды AI агенттер өз міндетіне алады.","Идеяны жазыңыз. Агенттер командасы жасайды. Тестілеуші сіздің көзіңізге түсер алдында тексереді.","Тегін, аккаунтсыз, трекерсіз: тақта, бірнеше робот және шешімді өзіңіз қабылдайсыз."]},{"n":21,"texts":["AI-gile: бағдарламалайтын AI агенттермен жұмыс істеуге арналған канбан тақтасы. Карталарды олар алады; сіз сынап, қабылдайсыз. Соңғы сөз әрқашан сізде.","Әр жобаға лид және AI агенттер командасы беріледі. Кез келген картаға пікір жазсаңыз, команда бірден жұмысқа кіріседі, ал сіз басқа іспен айналыса аласыз.","Өз компьютеріңізде жұмыс істейтін тегін жеке тапсырмалар тақтасы. Жұмысшылар роботтар, ал басты шешім сізде. Иә деп айтатын адам сіз боласыз, әрқашан."]},{"n":34,"texts":["Идеяларды тақтаға қоясыз. AI агенттер командасы оларды жұмыс істейтін мүмкіндіктерге айналдырады, сынайды және сынап көру қадамдарымен қайтарады. Сіз айтпайынша ештеңе дайын болып саналмайды. Соңғы шешім әрқашан сізде, жұмысты роботтар істейді.","AI-gile: Рич қазір өзі басқаратын агенттердің көп көмегімен жасаған үйде жасалған канбан тақтасы. Ол тегін, компьютеріңізде жұмыс істейді және сатылмайды, достармен бөлісіледі. Бұл жай ғана қызық әрі достық жоба.","Backlog-тан бастап Дайын-ға дейінгі бағандары бар қарапайым канбан тақтасын елестетіңіз, тек карталарды AI агенттер алады. Олар барысын хабарлайды, қиналса сұрайды және әрқашан сіздің келісіміңізді күтеді. Дәл жақсы команда сияқты."]},{"n":55,"texts":["AI-gile: командасы AI агенттерден құралған канбан тақтасы. Әр жобада жұмысты жоспарлайтын лид пен оны жасайтын көмекшілер бар. Мүмкіндік дайын болғанда AI тестілеуші оны сынап, скриншот түсіреді, содан кейін ол сіздің үйіндіңізге түседі. Қабылдаңыз немесе пікір жазыңыз, сонда олар қайта жасайды. Бәрі бір орында, бір тыныш тақтада.","Бұл бір адамның бірнеше AI кодтау сессиясын қатар бақылауының жолы ретінде басталып, шынайы тақтаға айналды. Ол сіздің құрылғыңызда жұмыс істейді, аккаунтты қажет етпейді және трекерлері жоқ. Достарға және қызыққандарға тегін. Сонымен бірге ол аяқталмаған, сондықтан өрескел тұстар мен кездейсоқ тосынсыйларды күтіңіз. Ерте кезеңде бұл табиғи нәрсе.","Міне, адал нұсқа. Идеяларды әлі де өзіңіз ойлап табуыңыз керек, нәтижені де әлі өзіңіз тексересіз. AI-gile арасындағының бәрін істейді: карталарды ретке келтіреді, пікір жазғанда керекті агентті оятады, не өзгергенін нақты көрсетеді және соның бәрін сізге бір қысқа үйіндіге жинайды. Сонда таңертең шаршаған көзбен ештеңе іздеудің қажеті болмайды."]},{"n":89,"texts":["AI-gile: өз компьютеріңізде іске қосатын тегін канбан тақтасы. Адамдардың орнына әр жобада AI агенттер командасы бар: идеяларыңызды карталар мен жоспарға айналдыратын лид және карталарды басымдық бойынша алатын көмекшілер. Бірдеңе жасалғанда AI тестілеуші сынақ қадамдарын орындап, не көргенін көрсетеді. Содан кейін ол «Сізге» деп аталатын бір үйіндіде күтеді. Сіз қабылдайсыз немесе пікір жазасыз, сонда команда қайта көреді. Сізсіз ештеңе ешқашан Дайын-ға жетпейді. Осылайша не болып жатқанын әрдайым білесіз және ештеңе назардан тыс қалмайды, әрі бәрі бір қарапайым жерде тұрады.","Күтпеген бірнеше мүмкіндік. Түнгі күзет сіз ұйықтап жатқанда Орындау керек бағанын толтырып отырады, сіздің жауабыңызды қажет етпейтін карталарды таңдайды. Токен есептегіші агенттердің бүгін және осы аптада қанша жұмсағанын көрсетеді, ал No Token Mode оларға жұмсауды тоқтатуды айтады. Достарға хабар жаза аласыз, жеке хабарлар басынан аяғына дейін шифрланған. Тақта шамамен 120 тілде сөйлейді, соның ішінде голланд, фламанд, қарақшы және клингон тілдерінде. Мұның бәрі бір тиын тұрмайды, және ешкім оны сізге сатпақ емес. Бұл жай ғана қызықты іс.","AI-gile: шағын жеке жоба, компания емес. Рич бірнеше AI кодтау жобасын әр қолданбаны ашып тексермей-ақ қадағалағысы келді, сөйтіп ол агенттермен бірге осыған арналған тақта жасады да, сол тақтаның көмегімен қалғанын өзі жасады. Ол жабық пре-альфада, яғни бір уыс досқа әзірге, негізінен, жұмыс істейді. Мұнда баға беті де, ақпараттық бюллетень де, өсу жоспары да жоқ. Пайдалы болып көрінсе, ол сәл кеңірек ашылғанда байқап көруді сұрай аласыз. Бұл біздің шағын, ашық және асықпайтын эксперименті, ешбір уәдесіз."]},{"n":144,"texts":["AI-gile: бір адам мен көптеген AI агентке арналған канбан тақтасы. Ол өз компьютеріңізде жұмыс істейді және толықтай тегін. Сіз жобаларды қосасыз, әр жобаға лид және шағын команда беріледі. Лидпен Discord сияқты сөйлесіп, идеяны сипаттайсыз; лид оны карталар мен жоспарға айналдырады да, сіз «Бастау» түймесін басқанша күтеді. Команда карталарды басымдық бойынша өңдейді, тіл модельдеріне арнап жасалған қарапайым пәрмен жолын пайдаланады. Сізге бірдеңе қайтып келмес бұрын AI тестілеуші қолданбаның көшірмесінде қадамдарды орындап, скриншот қосады. Дайын жұмыс өзгерген файлдар мен айырмашылығымен сіздің үйіндіңізге түседі. Сіз қабылдайсыз немесе пікір қалдырасыз, сонда команда оянып, қайта әрекет етеді. Картаны Дайын-ға тек сіз ғана жылжыта аласыз. Осылайша бір адам көптеген жобаны қатар басқара алады. Сіз бастықсыз, бірақ әлдеқайда тыныш жағдайда, әрі шаршамай.","AI-gile-мен өтетін бір күн, шамамен. Кешке бірнеше пікір қалдырасыз: бұл түйме қате жерде, анау тізімді сұрыптау керек, қараңғы режим болса ше. Ұйықтауға кетесіз. Агенттер пікірлерді оқиды, өзгерістерді енгізеді, тексереді және сізге қайтарады. Егер Орындау керек бағаны босап қалса, түнгі күзет оны сіздің жауабыңызды қажет етпейтін карталармен бэклогтан толтырады. Таңертең бір қысқа үйінді тұрады: бірнеше сұрақ және сынайтын бірнеше нәрсе, әрқайсысы ұйқылы адам да орындай алатын қадамдармен және жұмыс істеп тұрғанын көрсететін скриншотпен. Басып шығасыз, жақсыларын қабылдайсыз, қалғанын қайтарасыз. Токен есептегіші мұның бәріне не кеткенін көрсетеді, ал No Token Mode үнемді апталарға арналған. Содан кейін таңғы ас ішесіз, оған агенттер әзірге көмектесе алмайды. Кешке тағы бір идея есіңізге түссе, тағы бір пікір жазасыз да, команда бәрін түсінетінін біліп, тыныш ұйықтайсыз. Күн сіздікі болып қала береді.","Алдымен, AI-gile не емес. Ол стартап емес, сатылмайды және ешкім деректеріңізді жинамайды. Бұл компьютеріңізде жұмыс істейтін, аккаунтсыз, трекерсіз және cookie-сіз тегін тақта. Ал не екені: барлық AI кодтау жобаларын бірден көретін бір ретті орын, мұнда карталарды агенттер командасы орындайды, шешімдерді сіз қабылдайсыз. Ол ұқсас карталарды біріктіреді, түсініксіз атауларды түзетеді және код жеңіл болып қала ма, соны бақылайды. Ол шамамен 120 тілде сөйлейді, голланд және фламанд тілдерінен қарақшы және клингон тіліне дейін. Достар бір-біріне жеке және шифрланған хабар жаза алады. Оны Рич және көптеген шыдамды агент жасады, негізінен өзін-өзі пайдаланып. Ол жабық пре-альфада, сондықтан кей жерде өрескел. Қызық көрінсе, сыпайы сұраңыз, ерте кіріп кетуіңіз мүмкін. Бұл тақта өзін-өзі жасады, сондықтан кейде қателесуі де мүмкін, бірақ оны бірге түзетеміз."]}],"quips":{"1":"Бір сөз. Батыл. Мүмкін тым батыл.","3":"Үш сөз. Көптеген өнім беттерінен әлдеқашан адалырақ.","8":"Сегіз сөз. Әлі де стендаптан қысқа.","21":"Айтпақшы, ұзындықтар сторипойнттар. Әрине.","55":"Елу бес сөз. Сіз оны оқып жатқанда екі карта бітті.","144":"Бұл ең ұзыны. 233 жоқ. Агенттер ұйықтауға кетті."}},"timeline":{"first-idea.name":"Алғашқы идея","first-idea.line":"Код әлі болмаған кездегі ең бірінші әңгіме.","first-board.name":"Алғашқы тақта","first-board.line":"Өз құрылысын өзі бақылайтын тақта: карталар, бағандар, сүйреп апару, жобалар.","team-roles.name":"Команда және рөлдер","team-roles.line":"Агент профильдері, команда үлгілері, кеңістіктер және кім не істейді.","install.name":"Орнату және шығарылымдар","install.line":"Дос орната алатын zip, өздігінен жаңару, арналар және кері қайтару.","usage-saver.name":"Шығынды үнемдеу","usage-saver.line":"Іске қосулардың құнын өлшеу, кодты жеңіл ұстау, лимитті үнемдеу.","friends.name":"Достар және бөлісу","friends.line":"Жеке хабарлар, шифрланған релей, шақырулар, рөлдер және ортақ жобалар.","languages.name":"Тілдер","languages.line":"Экрандағы барлық мәтін тіл файлында, алдымен голланд және фламанд тілдерімен.","ai-tester.name":"AI тестілеуші","ai-tester.line":"Тестілеуші әр тапсыруды алдымен тексеріп, не көргенін көрсетеді.","website.name":"Веб-сайт","website.line":"aigile.lol, тизер және осы уақыт сызығы.","streaming.name":"Чат және стримінг","streaming.line":"Discord, Twitch, OBS, стример режимі, GIF және эмодзи.","no-ai.name":"AI-сыз нұсқа","no-ai.line":"AI-сыз код жазатындарға арналған тақта және ашық тақталар.","night-watch.name":"Түнгі күзет","night-watch.line":"Күзетші мен Scrum Master сіз ұйықтағанда командаларды жұмыста ұстайды.","p-more.name":"Қалғанының бәрі","p-more.line":"Кезегін әлі күтіп тұрған кішірек идеялар.","p-android.name":"Телефон және Android","p-android.line":"Тақтаңызға телефоннан кіру, содан кейін жергілікті Android қолданбасы.","p-release.name":"Альфа және одан әрі","p-release.line":"Жабық альфа, жұмыс істейтін сайт, содан кейін бета.","p-languages.name":"Көбірек тілдер","p-languages.line":"Жүзден астам тіл және оқушыларға арналған тереңдетіп үйрену режимі.","p-engines.name":"Көбірек AI қозғалтқыштары","p-engines.line":"Әр агентке Claude, Codex немесе Gemini таңдаңыз.","p-pro.name":"Кәсіби тәжірибе","p-pro.line":"Тәуекел белгілері, біріктіру қақпалары, оқиға карталары және қорғау шаралары.","p-self.name":"Сізге қамқорлық","p-self.line":"Шаршау режимі, өзіңізге қамқор болу туралы еске салғыштар және 4:20.","p-servers.name":"Серверлер және масштаб","p-servers.line":"Жаһандық сервер параметрлері, рөлдер және өсуді жоспарлау.","p-livestream.name":"Стримінгтің қосымшалары","p-livestream.line":"Twitch чаты, жеке эмодзилер және ашық тікелей көрініс."},"words":{"button":"📖 Әзірлеуші сөздері","h":"📖 Әзірлеуші сөздерінің түсіндірмесі","intro":"Әзірлеушілер (және AI командалары) қолданатын сөздер, қарапайым тілмен.","search":"Сөз іздеу…","none":"Бұған сәйкес сөз жоқ.","close":"Жабу","list":[{"id":"backlog","word":"Backlog","text":"Әлі жоспарланбаған идеялар мен жұмыс. Орындау керекке көшкенше, онда ештеңе жасалмайды."},{"id":"sprint","word":"Спринт","text":"Аяқтауға келісілген карталар жиыны бар жұмыстың қысқа кезеңі (көбіне бір-екі апта).","also":["спринттер","спринтке","спринті"]},{"id":"standup","word":"Стендап","text":"Жылдам ауызша есеп: әр мүше не істеді, келесіде не істейді және не кедергі келтіріп тұр.","also":["стендап","стендаптар","stand-up"]},{"id":"bug","word":"Баг","text":"Дұрыс істеуге тиісті, бірақ істемейтін нәрсе.","also":["бағтар","қате"]},{"id":"test","word":"Тест","text":"Бітірілген жұмысты қабылдамас бұрын, ол сұралғанды істейтінін тексеру үшін байқап көру.","also":["тесттер","тестілеу"],"noTip":1},{"id":"commit","word":"Коммит","text":"Кодтың сақталған көшірмесі, не өзгергені туралы қысқа жазбасымен. Әрқашан біреуіне қайта оралуға болады.","also":["коммиттер"]},{"id":"push","word":"Push","text":"Сақталған көшірмелерді (коммиттерді) осы компьютерден GitHub-қа жіберу, сонда олар сақтық көшірмеленіп, ортақ болады."},{"id":"branch","word":"Branch","text":"Кодтағы жеке жұмыс желісі, сонда негізгі нұсқаға тиіспей өзгерістер енгізуге болады.","also":["branch-тар","тармақ"]},{"id":"merge","word":"Merge","text":"Branch өзгерістерін негізгі нұсқаға қайта біріктіру."},{"id":"repo","word":"Репо","text":"Жобаның код бумасы және коммиттердің толық тарихы, әдетте GitHub-та да сақталады.","also":["репозиторий"]},{"id":"refactor","word":"Рефакторинг","text":"Кодтың не істейтінін өзгертпей реттеу: кішірек файлдар, анығырақ атаулар, аз қайталау."},{"id":"deploy","word":"Deploy","text":"Жаңа нұсқаны жұмысқа қосу, мысалы, адамдар қолданатын серверге."},{"id":"kanban","word":"Kanban","text":"Бағандары (Орындау керек, Орындалуда, Дайын) бар тақта, жұмыс орындалған сайын карталар солдан оңға жылжиды."},{"id":"wip","word":"WIP шегі","text":"Орындалып жатқан жұмыс: бағанда ең көбі қанша карта болуы керек, сонда команда көбірек бастамас бұрын бітіреді.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Branch өзгерістерін тексеріп, негізгі нұсқаға біріктіруді сұрау.","also":["PR"]},{"id":"hook","word":"Hook","text":"Белгіленген сәтте өздігінен орындалатын шағын команда, мысалы, AI сессиясы басталғанда, сонда команда пікірлеріңізді естиді.","also":["hook-тар","hooks"]},{"id":"token","word":"Токен","text":"AI пайдалану есептелетін бірлік: оқылған немесе жазылған мәтіннің шамамен бірнеше әрпі. Токен аз болса, тарифіңізден көбірек қалады.","also":["токендер"]},{"id":"agent","word":"Агент","text":"Тапсырма бойынша өздігінен жұмыс істейтін AI: кодты оқиды, өзгерістер енгізеді, тексерулер жүргізеді және есеп береді.","also":["агенттер","агенттің"]}]}};
